// The second fence (Perro's Python code is the first). An allowlist: only
// these requests, only in Perro's own account, pass. No deleting, no
// collaborators, hooks, keys, secrets, Actions or settings, and no files
// under .github/ (where workflows live). A repo is made public only by the
// one request below, which Perro's code sends only after the owner approves.
const OWNER = 'perro-agent';
const REPO = '[A-Za-z0-9_.-]{1,100}';
const r = $input.first().json.body || {};
const method = String(r.method || 'GET').toUpperCase();
const url = String(r.url || '');
const body = r.body ?? {};
const bodyText = JSON.stringify(body);
const base = 'https://api.github.com/';
const path = url.startsWith(base) ? url.slice(base.length) : null;
const allowed = [
  ['GET', /^user$/],
  ['GET', /^user\/repos$/],
  ['POST', /^user\/repos$/],
  ['GET', new RegExp('^repos/' + OWNER + '/' + REPO + '(/[A-Za-z0-9_./-]*)?$')],
  ['POST', new RegExp('^repos/' + OWNER + '/' + REPO + '/git/(blobs|trees|commits|refs)$')],
  ['PATCH', new RegExp('^repos/' + OWNER + '/' + REPO + '/git/refs/heads/[A-Za-z0-9_.-]+$')],
  ['PATCH', new RegExp('^repos/' + OWNER + '/' + REPO + '$')],
];
let refused = '';
if (path === null) refused = 'that address is not GitHub\'s API';
else if (/[?#%\\]|\.\.|\/\//.test(path)) refused = 'that kind of address is not allowed (options go in query)';
else if (!allowed.some(([m, re]) => m === method && re.test(path))) refused = method + ' ' + path + ' is not something Perro may do on GitHub';
else if (/\.github\//.test(bodyText)) refused = 'files under .github/ (workflows) are not allowed';
else if (method === 'POST' && path === 'user/repos' && (body.private !== true || 'visibility' in body)) refused = 'new repositories must be private';
else if (method === 'PATCH' && path.includes('/git/refs/') && body.force !== false) refused = 'branch updates must not be forced';
else if (method === 'PATCH' && !path.includes('/git/') && bodyText !== '{"private":false}') refused = 'the only repository setting Perro may change is making it public, after approval';
return [{ json: { method, url, query: r.query || {}, body, write: method !== 'GET', refused } }];
